const items = $input.all();

if (!items.length) {
  throw new Error('No input item found');
}

const item = items[0];

let fileContent = '';

if (item.json.data || item.json.content || item.json.text || item.json.fileContent) {
  fileContent =
    item.json.data ||
    item.json.content ||
    item.json.text ||
    item.json.fileContent;
} else if (item.binary) {
  const binaryKey = Object.keys(item.binary)[0];

  if (!binaryKey) {
    throw new Error('Binary file found, but binary key is missing');
  }

  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  fileContent = buffer.toString('utf8');
} else {
  throw new Error('No text or binary file content found');
}

const title = 'VPN ve Uzaktan Erişim Sorunları';
const category = 'vpn';

const cleaned = fileContent
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!cleaned) {
  throw new Error('File content is empty after cleaning');
}

const paragraphs = cleaned
  .split(/\n\s*\n/)
  .map(p => p.trim())
  .filter(p => p.length > 0);

return paragraphs.map((paragraph, index) => ({
  json: {
    document_id: 'vpn-remote-access',
    title,
    category,
    chunk_index: index,
    content: paragraph
  }
}));

const embedding = $json.embeddings?.[0];

if (!embedding) {
  throw new Error('Embedding response not found');
}

const chunk = $('Create Chunks').item.json;

function sqlEscape(value) {
  return String(value ?? '').replace(/'/g, "''");
}

const documentId = chunk.document_id;
const title = chunk.title;
const category = chunk.category;
const chunkIndex = chunk.chunk_index;
const content = chunk.content;
const embeddingVector = `[${embedding.join(',')}]`;

const insertQuery = `
INSERT INTO document_chunks (
  document_id,
  title,
  category,
  chunk_index,
  content,
  embedding
)
VALUES (
  '${sqlEscape(documentId)}',
  '${sqlEscape(title)}',
  '${sqlEscape(category)}',
  ${chunkIndex},
  '${sqlEscape(content)}',
  '${embeddingVector}'::vector
);
`;

return {
  json: {
    document_id: documentId,
    title,
    category,
    chunk_index: chunkIndex,
    content,
    embedding_vector: embeddingVector,
    insert_query: insertQuery
  }
};
